-- eos schema lint. Generated by `eos scaffold db-safety`; yours to edit.
-- Run against a freshly migrated database (CI does this in .github/workflows/db-safety.yml):
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f scripts/db/schema_lint.sql
-- Fails (exit 3) on: foreign keys with no index whose leading columns are the FK columns, and money-like
-- columns stored as real / double precision (names like *_rate, *_pct are skipped) or money. Warns (NOTICE) on timestamp without time zone.
-- See .eos/packs/ref/data/postgres-indexing.md and data/keys-money-time.md. Exempt a reviewed case by
-- adding its "schema.table.column" (or "schema.table.constraint") to the allow list below, with a reason.
\set QUIET on
\pset footer off
CREATE TEMP TABLE eos_allow (item text PRIMARY KEY, reason text NOT NULL);
-- INSERT INTO eos_allow VALUES ('public.audit_log.actor_id_fkey', 'append-only table, parent rows never deleted');

CREATE TEMP VIEW eos_fk_missing_index AS
SELECT n.nspname || '.' || cl.relname || '.' || c.conname AS item,
       pg_get_constraintdef(c.oid) AS definition
FROM pg_constraint c
JOIN pg_class cl ON cl.oid = c.conrelid
JOIN pg_namespace n ON n.oid = cl.relnamespace
WHERE c.contype = 'f'
  AND c.conparentid = 0
  AND n.nspname NOT IN ('pg_catalog', 'information_schema')
  AND n.nspname NOT LIKE 'pg_toast%'
  AND NOT EXISTS (
    SELECT 1
    FROM pg_index i
    WHERE i.indrelid = c.conrelid
      AND i.indpred IS NULL
      AND (i.indkey::int2[])[0:cardinality(c.conkey) - 1] @> c.conkey
      AND (i.indkey::int2[])[0:cardinality(c.conkey) - 1] <@ c.conkey
  )
  AND n.nspname || '.' || cl.relname || '.' || c.conname NOT IN (SELECT item FROM eos_allow);

CREATE TEMP VIEW eos_money_float AS
SELECT table_schema || '.' || table_name || '.' || column_name AS item, data_type
FROM information_schema.columns
WHERE table_schema NOT IN ('pg_catalog', 'information_schema')
  AND (
    data_type = 'money'
    OR (data_type IN ('real', 'double precision')
        AND column_name ~* '(amount|price|cost|balance|total|fee|tax|salary|wage|revenue|payment|refund|discount|charge|payout|credit|debit|money|cents)'
        AND column_name !~* '(^|_)(rate|ratio|pct|percent|score|weight|factor)s?(_|$)')
  )
  AND table_schema || '.' || table_name || '.' || column_name NOT IN (SELECT item FROM eos_allow);

CREATE TEMP VIEW eos_naive_timestamp AS
SELECT table_schema || '.' || table_name || '.' || column_name AS item
FROM information_schema.columns c
JOIN information_schema.tables t USING (table_schema, table_name)
WHERE c.table_schema NOT IN ('pg_catalog', 'information_schema')
  AND t.table_type = 'BASE TABLE'
  AND c.data_type = 'timestamp without time zone'
  AND c.table_schema || '.' || c.table_name || '.' || c.column_name NOT IN (SELECT item FROM eos_allow);

\echo '== foreign keys without a supporting index (deletes/updates on the parent scan the child)'
SELECT * FROM eos_fk_missing_index ORDER BY item;
\echo '== money-like columns stored as floating point or the money type (use numeric or integer minor units)'
SELECT * FROM eos_money_float ORDER BY item;
\echo '== timestamp without time zone (warning only; prefer timestamptz)'
SELECT * FROM eos_naive_timestamp ORDER BY item;

DO $$
DECLARE
  fk int := (SELECT count(*) FROM eos_fk_missing_index);
  money int := (SELECT count(*) FROM eos_money_float);
  naive int := (SELECT count(*) FROM eos_naive_timestamp);
BEGIN
  IF naive > 0 THEN
    RAISE NOTICE 'eos schema lint: % timestamp without time zone column(s); prefer timestamptz', naive;
  END IF;
  IF fk + money > 0 THEN
    RAISE EXCEPTION 'eos schema lint failed: % unindexed foreign key(s), % money column(s) as float/money', fk, money;
  END IF;
  RAISE NOTICE 'eos schema lint: ok';
END $$;
